WITH unpacked AS (SELECT id, service, host, level, latency_ms, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, SHIFTRIGHT(status_code, 2) AS status_code_high, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs WHERE level IN ('INFO', 'DEBUG')) SELECT *, CUME_DIST() OVER (PARTITION BY host ORDER BY latency_ms DESC NULLS LAST) AS latency_ms_cume_dist, SUM(status_code_high) OVER (PARTITION BY tier) AS tier_sum_status_code_high, LAG(duration_sec, 2, 0) OVER (PARTITION BY host ORDER BY duration_sec ASC, id ASC) AS prev_duration_sec FROM unpacked
